    kwargs=dict(species='Na', alpha=1., T_K=1500.,molar_mass_kg_mol=.02298976928,
                overhead_pressure_pa=1000.,p_eq_pa=.7,p_bulk_pa=.6,melt_surface_area_m2=AREA)
